const S = W.store;
// running: the power bar is the cooling: how many of the three compressors run. The chambers' temperature follows slowly
// (thousands of tonnes of chilli hold the cold): about two compressors keep 4 °C on a hot day; more pull it down to the set
// point (2 °C: the thermostat stops there). Over the limit the condenser can't get rid of the heat: the discharge pressure
// climbs and a compressor's high-pressure cutout stops it (a protection).
// 🚩 "door": a dock door left open: warm wet air pours in along the floor, the coils frost up, the temperature and the
// damp rise. 🚩 "cut": the power fails: the compressors stop; after a few seconds the generator runs two of them.
const sign = W.group();
sign.add(W.text('JARVIS · మిర్చి కోల్డ్ స్టోరేజ్', { size: 100, at: [0, 980, 1032], color: '#a8322a', bg: '#f2f2ee' }));
W.add(sign, { label: 'బోర్డ్' });
W.throttle({ label: 'కూలింగ్', rise: 0.3, fall: 0.3, start: 0.67 });
const cv = W.sound({ kind: 'motor', label: 'కంప్రెసర్లు', gain: 0.5, f0: 45 });
const fv = W.sound({ kind: 'fans', label: 'ఎవాపరేటివ్ కండెన్సర్లు', gain: 0.75 });
const av = W.sound({ kind: 'fans', label: 'ఎయిర్ కూలర్లు', gain: 0.25 });
const gv = W.sound({ kind: 'motor', label: 'జనరేటర్', gain: 0.5, f0: 40 });
const lv = W.sound({ kind: 'hum', label: 'లిఫ్ట్', gain: 0.08, f0: 120 });
const vap = S.plume(S.cdG, [-3200, 880, -620], { n: 10, life: 5, r: 120, rise: 700, drift: 400, op: 0.35, color: '#f4f6f6' });
const smoke = S.plume(S.genG, S.genAt, { n: 8, life: 4, r: 40, rise: 400, drift: 260, op: 0.4, color: '#7a7a78' });
let hudT = 0, T = 5, RH = 66, k = 0, n = 0, cutT = 0, gen = 0, frost = 0;
S.st = { k: 0, door: 0 };
W.onTick((t, dt) => {
  const s = W.env.spool, over = W.env.over, door = W.env.flag('door'), cut = W.env.flag('cut'), hr = W.env.hour == null ? 12 : W.env.hour;
  cutT = cut ? cutT + dt : 0;
  gen += ((cut && cutT > 6 ? 1 : 0) - gen) * Math.min(1, dt * 1.5);
  n = s > 0.02 ? Math.max(1, Math.round(3 * Math.min(1, s))) : 0;
  if (over) n = Math.min(n, 2);
  if (cut) n = cutT > 6 ? Math.min(n, 2) : 0;
  const atSet = T <= 2.05;
  k += ((atSet ? Math.min(n, 1) : n) / 3 - k) * Math.min(1, dt * 1.5);
  S.st.k = k; S.st.door = door ? 1 : 0;
  const tout = 26 + 9 * Math.max(0, Math.sin(((hr - 6) / 12) * Math.PI));
  const target = Math.max(2, 4 + (0.62 - n / 3) * 26 + (door ? 7 : 0) + (tout - 33) * 0.08);
  T += (target - T) * Math.min(1, dt * 0.05);
  RH += ((door ? 86 : 66) - RH) * Math.min(1, dt * 0.15);
  frost += ((door ? 1 : 0) - frost) * Math.min(1, dt * 0.08);
  S.coilM.color.setRGB(0.54 + 0.4 * frost, 0.6 + 0.36 * frost, 0.65 + 0.33 * frost);
  S.doors[1].position.x = door ? 340 : 0;
  S.comp.forEach((f, i) => { f.rotation.x += dt * 25 * (i < n && !(atSet && i > 0) ? 1 : 0); S.pilot[i].emissive.set(cut && cutT <= 6 ? 0xff3a2a : over && i === 2 ? 0xff3a2a : 0x3aff6a); S.pilot[i].emissiveIntensity = i < n || cut || (over && i === 2) ? 2 : 0.15; });
  S.cFans.forEach((f) => { f.rotation.y += dt * 12 * Math.min(1, k * 1.5); });
  S.cab.position.y = 130 + 400 * (1 + Math.sin(t * 0.12)) ;
  S.fork.position.x = -600 + 900 * Math.sin(t * 0.18); S.fork.rotation.y = Math.cos(t * 0.18) > 0 ? 0 : Math.PI;
  S.sock.rotation.y = 0.3 * Math.sin(t * 0.4);
  vap(dt, Math.min(1, k * 1.5)); smoke(dt, gen);
  cv.set(k); fv.set(Math.min(1, k * 1.5)); av.set(cut && cutT <= 6 ? 0 : 0.25 + 0.45 * k); gv.set(gen); lv.set(0.5);
  S.step(t, dt, k);
  if (t - hudT > 0.3) {
